     1→package io.exoreaction.synthesis.index;
     2→
     3→import org.apache.lucene.analysis.Analyzer;
     4→import org.apache.lucene.analysis.standard.StandardAnalyzer;
     5→import org.apache.lucene.document.Document;
     6→import org.apache.lucene.index.*;
     7→import org.apache.lucene.queryparser.classic.MultiFieldQueryParser;
     8→import org.apache.lucene.queryparser.classic.ParseException;
     9→import org.apache.lucene.queryparser.classic.QueryParser;
    10→import org.apache.lucene.search.*;
    11→import org.apache.lucene.store.Directory;
    12→import org.apache.lucene.store.FSDirectory;
    13→
    14→import java.io.Closeable;
    15→import java.io.IOException;
    16→import java.nio.file.Files;
    17→import java.nio.file.Path;
    18→import java.util.*;
    19→
    20→/**
    21→ * Lucene search index wrapper providing a simple API for Synthesis.
    22→ *
    23→ * <p>Encapsulates all Lucene complexity behind three operations:
    24→ * <ul>
    25→ *   <li>{@link #addDocument} -- add or update a document in the index</li>
    26→ *   <li>{@link #search} -- query the index with a search string</li>
    27→ *   <li>{@link #deleteAll} -- clear the index for full rebuild</li>
    28→ * </ul>
    29→ *
    30→ * <p>Two open modes:
    31→ * <ul>
    32→ *   <li><b>Write mode</b> ({@code new SearchIndex(path)}) -- acquires Lucene's exclusive
    33→ *       {@code write.lock}. Use for scan, maintain, and watch operations.</li>
    34→ *   <li><b>Read-only mode</b> ({@code SearchIndex.openReadOnly(path)}) -- opens a
    35→ *       {@link DirectoryReader} directly; no lock is acquired. Multiple processes can
    36→ *       search the same index concurrently without contention.</li>
    37→ * </ul>
    38→ *
    39→ * <p>Thread safety: This class is NOT thread-safe. Use from a single thread
    40→ * or synchronize externally.
    41→ */
    42→public class SearchIndex implements Closeable {
    43→
    44→    private final Path indexPath;
    45→    private final Analyzer analyzer;
    46→    private final Directory directory;
    47→    private IndexWriter writer;       // null in read-only mode
    48→    private final boolean readOnly;
    49→    private final boolean indexEmpty; // true when read-only and no segments exist yet
    50→
    51→    /** Fields searched by default, with relevance boost weights. */
    52→    private static final String[] SEARCH_FIELDS = {
    53→            DocumentFields.FILENAME,
    54→            DocumentFields.HEADINGS,
    55→            DocumentFields.KEYWORDS,
    56→            DocumentFields.SUMMARY,
    57→            DocumentFields.CONTENT,
    58→            DocumentFields.RELATIVE_PATH
    59→    };
    60→
    61→    /** Boost factors: headings and keywords rank higher than raw content. */
    62→    private static final Map<String, Float> FIELD_BOOSTS = Map.of(
    63→            DocumentFields.FILENAME, 3.0f,
    64→            DocumentFields.HEADINGS, 2.5f,
    65→            DocumentFields.KEYWORDS, 2.0f,
    66→            DocumentFields.SUMMARY, 1.5f,
    67→            DocumentFields.CONTENT, 1.0f,
    68→            DocumentFields.RELATIVE_PATH, 1.0f
    69→    );
    70→
    71→    /**
    72→     * Opens or creates a search index at the given path in <b>write mode</b>.
    73→     *
    74→     * <p>Acquires Lucene's exclusive {@code write.lock}. Use only for commands
    75→     * that modify the index (scan, maintain, watch). For read-only access use
    76→     * {@link #openReadOnly(Path)}.
    77→     *
    78→     * @param indexPath directory where the Lucene index files are stored
    79→     */
    80→    public SearchIndex(Path indexPath) throws IOException {
    81→        this.indexPath = indexPath;
    82→        this.analyzer = new StandardAnalyzer();
    83→        this.readOnly = false;
    84→        this.indexEmpty = false; // writer initialises segments on creation
    85→
    86→        Files.createDirectories(indexPath);
    87→        this.directory = FSDirectory.open(indexPath);
    88→        openWriter();
    89→    }
    90→
    91→    /**
    92→     * Opens an existing search index in <b>read-only mode</b>.
    93→     *
    94→     * <p>Uses {@link DirectoryReader#open(Directory)} which does <em>not</em>
    95→     * acquire any file lock. Multiple processes can call this concurrently on
    96→     * the same index directory without contention.
    97→     *
    98→     * @param indexPath directory where the Lucene index files are stored
    99→     * @return a read-only SearchIndex; write operations throw {@link IllegalStateException}
   100→     * @throws IOException if the index directory cannot be opened
   101→     */
   102→    public static SearchIndex openReadOnly(Path indexPath) throws IOException {
   103→        return new SearchIndex(indexPath, true);
   104→    }
   105→
   106→    private SearchIndex(Path indexPath, boolean readOnly) throws IOException {
   107→        this.indexPath = indexPath;
   108→        this.analyzer = new StandardAnalyzer();
   109→        this.readOnly = readOnly;
   110→
   111→        Files.createDirectories(indexPath);
   112→        this.directory = FSDirectory.open(indexPath);
   113→        // writer stays null — DirectoryReader.open(directory) used per search call
   114→        // If no segments exist yet, mark as empty so search methods return [] gracefully
   115→        this.indexEmpty = !DirectoryReader.indexExists(directory);
   116→    }
   117→
   118→    private void openWriter() throws IOException {
   119→        IndexWriterConfig config = new IndexWriterConfig(analyzer);
   120→        config.setOpenMode(IndexWriterConfig.OpenMode.CREATE_OR_APPEND);
   121→        this.writer = new IndexWriter(directory, config);
   122→    }
   123→
   124→    /** Opens a reader appropriate for the current mode. */
   125→    private DirectoryReader openReader() throws IOException {
   126→        return readOnly ? DirectoryReader.open(directory) : DirectoryReader.open(writer);
   127→    }
   128→
   129→    /**
   130→     * Adds a document to the index. If a document with the same path
   131→     * already exists, it is replaced (update semantics).
   132→     *
   133→     * @throws IllegalStateException if this index was opened in read-only mode
   134→     */
   135→    public void addDocument(Document doc) throws IOException {
   136→        requireWritable();
   137→        String path = doc.get(DocumentFields.PATH);
   138→        if (path != null) {
   139→            // Delete existing document with same path (upsert)
   140→            writer.updateDocument(new Term(DocumentFields.RELATIVE_PATH,
   141→                    doc.get(DocumentFields.RELATIVE_PATH)), doc);
   142→        } else {
   143→            writer.addDocument(doc);
   144→        }
   145→    }
   146→
   147→    /**
   148→     * Commits all pending changes to the index.
   149→     * Must be called after adding documents to make them searchable.
   150→     *
   151→     * @throws IllegalStateException if this index was opened in read-only mode
   152→     */
   153→    public void commit() throws IOException {
   154→        requireWritable();
   155→        writer.commit();
   156→    }
   157→
   158→    /**
   159→     * Deletes all documents from the index.
   160→     * Used for full rebuild.
   161→     *
   162→     * @throws IllegalStateException if this index was opened in read-only mode
   163→     */
   164→    public void deleteAll() throws IOException {
   165→        requireWritable();
   166→        writer.deleteAll();
   167→        writer.commit();
   168→    }
   169→
   170→    /**
   171→     * Deletes a single document by its relative path.
   172→     * Used by incremental maintenance to remove deleted files.
   173→     *
   174→     * @param relativePath the relative path of the file to remove
   175→     * @throws IllegalStateException if this index was opened in read-only mode
   176→     */
   177→    public void deleteByRelativePath(String relativePath) throws IOException {
   178→        requireWritable();
   179→        writer.deleteDocuments(new Term(DocumentFields.RELATIVE_PATH, relativePath));
   180→    }
   181→
   182→    /**
   183→     * Returns the number of documents in the index.
   184→     */
   185→    public int documentCount() {
   186→        if (!readOnly) {
   187→            return writer.getDocStats().numDocs;
   188→        }
   189→        if (indexEmpty) return 0;
   190→        try (DirectoryReader reader = DirectoryReader.open(directory)) {
   191→            return reader.numDocs();
   192→        } catch (IOException e) {
   193→            return 0;
   194→        }
   195→    }
   196→
   197→    private void requireWritable() {
   198→        if (readOnly) {
   199→            throw new IllegalStateException(
   200→                    "SearchIndex is open in read-only mode; use new SearchIndex(path) for write access");
   201→        }
   202→    }
   203→
   204→    /**
   205→     * Searches the index with a query string.
   206→     *
   207→     * <p>Searches across filename, headings, keywords, summary, and content
   208→     * with relevance boosting. Supports Lucene query syntax:
   209→     * <ul>
   210→     *   <li>Simple terms: {@code "testing strategy"}</li>
   211→     *   <li>Exact phrases: {@code "\"NCI Protocol\""}</li>
   212→     *   <li>Boolean: {@code "testing AND strategy"}</li>
   213→     *   <li>Wildcards: {@code "test*"}</li>
   214→     *   <li>Field-specific: {@code "language:Java"}</li>
   215→     * </ul>
   216→     *
   217→     * @param queryString the search query
   218→     * @param maxResults  maximum number of results to return
   219→     * @return ranked list of search results
   220→     */
   221→    public List<SearchResult> search(String queryString, int maxResults) throws IOException {
   222→        if (queryString == null || queryString.isBlank() || indexEmpty) {
   223→            return List.of();
   224→        }
   225→
   226→        try (DirectoryReader reader = openReader()) {
   227→            IndexSearcher searcher = new IndexSearcher(reader);
   228→
   229→            Query query = buildQuery(queryString);
   230→            TopDocs topDocs = searcher.search(query, maxResults);
   231→
   232→            List<SearchResult> results = new ArrayList<>();
   233→            for (ScoreDoc scoreDoc : topDocs.scoreDocs) {
   234→                Document doc = searcher.storedFields().document(scoreDoc.doc);
   235→                results.add(toSearchResult(doc, scoreDoc.score));
   236→            }
   237→
   238→            return results;
   239→        } catch (ParseException e) {
   240→            // If query parsing fails, try as a simple term query
   241→            return searchSimple(queryString, maxResults);
   242→        }
   243→    }
   244→
   245→    /**
