   736→                Path.of(doc.get(DocumentFields.PATH)),
   737→                doc.get(DocumentFields.RELATIVE_PATH),
   738→                score,
   739→                doc.get(DocumentFields.FILENAME),
   740→                doc.get(DocumentFields.FILE_TYPE),
   741→                doc.get(DocumentFields.LANGUAGE),
   742→                doc.get(DocumentFields.SUMMARY) != null ? doc.get(DocumentFields.SUMMARY) : "",
   743→                doc.get(DocumentFields.HEADINGS) != null ? doc.get(DocumentFields.HEADINGS) : "",
   744→                doc.get(DocumentFields.STRUCTURE) != null ? doc.get(DocumentFields.STRUCTURE) : "",
   745→                sizeBytes,
   746→                doc.get(DocumentFields.REPOSITORY),
   747→                doc.get(DocumentFields.SUB_WORKSPACE)
   748→        );
