   755→     * {@link DocumentFields#SUB_WORKSPACE} value. Documents without a
   756→     * sub-workspace are grouped under an empty-string key.
   757→     *
   758→     * @return map from sub-workspace name to file count
   759→     */
   760→    public Map<String, Long> getSubWorkspaceCounts() throws IOException {
   761→        if (indexEmpty) return Map.of();
   762→        Map<String, Long> counts = new HashMap<>();
   763→
   764→        try (DirectoryReader reader = openReader()) {
   765→            IndexSearcher searcher = new IndexSearcher(reader);
   766→            TopDocs topDocs = searcher.search(new MatchAllDocsQuery(), Integer.MAX_VALUE);
   767→
   768→            for (ScoreDoc scoreDoc : topDocs.scoreDocs) {
   769→                Document doc = searcher.storedFields().document(scoreDoc.doc);
   770→                String subWorkspace = doc.get(DocumentFields.SUB_WORKSPACE);
   771→                if (subWorkspace == null) {
   772→                    subWorkspace = "";
   773→                }
   774→                counts.merge(subWorkspace, 1L, Long::sum);
