    private SearchResult toSearchResult(Document doc, float score) {
        String sizeStr = doc.get(DocumentFields.SIZE);
        long sizeBytes = sizeStr != null ? Long.parseLong(sizeStr) : 0;

        return new SearchResult(
                Path.of(doc.get(DocumentFields.PATH)),
                doc.get(DocumentFields.RELATIVE_PATH),
                score,
                doc.get(DocumentFields.FILENAME),
                doc.get(DocumentFields.FILE_TYPE),
                doc.get(DocumentFields.LANGUAGE),
                doc.get(DocumentFields.SUMMARY) != null ? doc.get(DocumentFields.SUMMARY) : "",
                doc.get(DocumentFields.HEADINGS) != null ? doc.get(DocumentFields.HEADINGS) : "",
                doc.get(DocumentFields.STRUCTURE) != null ? doc.get(DocumentFields.STRUCTURE) : "",
                sizeBytes,
                doc.get(DocumentFields.REPOSITORY),
                doc.get(DocumentFields.SUB_WORKSPACE)
        );
    }

    /**
     * Returns the number of indexed documents grouped by sub-workspace.
     *
     * <p>Iterates all documents in the index and counts files per
     * {@link DocumentFields#SUB_WORKSPACE} value. Documents without a
     * sub-workspace are grouped under an empty-string key.
     *
     * @return map from sub-workspace name to file count
     */
    public Map<String, Long> getSubWorkspaceCounts() throws IOException {
        if (indexEmpty) return Map.of();
        Map<String, Long> counts = new HashMap<>();

        try (DirectoryReader reader = openReader()) {
            IndexSearcher searcher = new IndexSearcher(reader);
            TopDocs topDocs = searcher.search(new MatchAllDocsQuery(), Integer.MAX_VALUE);

            for (ScoreDoc scoreDoc : topDocs.scoreDocs) {
                Document doc = searcher.storedFields().document(scoreDoc.doc);
                String subWorkspace = doc.get(DocumentFields.SUB_WORKSPACE);
                if (subWorkspace == null) {
                    subWorkspace = "";
                }
                counts.merge(subWorkspace, 1L, Long::sum);
            }
        }

        return counts;
    }

    @Override
    public void close() throws IOException {
        if (writer != null) {
            writer.close();
        }
        if (directory != null) {
            directory.close();
        }
    }
}

package io.exoreaction.synthesis.index;

/**
 * Constants for Lucene document field names.
 * Centralized here to avoid magic strings scattered across the codebase.
 */
public final class DocumentFields {

    private DocumentFields() {}

    // --- Identity fields (stored, not tokenized) ---

    /** Absolute file path (stored for retrieval, not searched). */
    public static final String PATH = "path";

    /** Relative path from workspace root (stored and searchable). */
    public static final String RELATIVE_PATH = "relativePath";

    /** File name without directory (searchable, stored). */
    public static final String FILENAME = "filename";

    /** File extension including dot, e.g. ".java" (keyword field, stored). */
    public static final String EXTENSION = "extension";

    // --- Classification fields (keyword/facet) ---

    /** File type classification: MARKDOWN, CODE, YAML, etc. */
    public static final String FILE_TYPE = "fileType";

    /** Programming language if detected: Java, Python, etc. */
    public static final String LANGUAGE = "language";

    // --- Content fields (tokenized, searchable) ---

    /** Full text content of the file (main search field). */
    public static final String CONTENT = "content";

    /** Document headings / titles (boosted for relevance). */
    public static final String HEADINGS = "headings";

    /** Extracted keywords (boosted for relevance). */
    public static final String KEYWORDS = "keywords";

    /** Analysis summary (boosted for relevance). */
    public static final String SUMMARY = "summary";

    // --- Metadata fields (stored for display) ---

    /** File size in bytes (stored as string for display). */
    public static final String SIZE = "size";

    /** Last modified timestamp as epoch millis (stored for sorting). */
    public static final String LAST_MODIFIED = "lastModified";

    /** Content hash for duplicate detection. */
    public static final String CONTENT_HASH = "contentHash";

    /** Structural description of the file. */
    public static final String STRUCTURE = "structure";

    /** Repository identifier for multi-repo workspaces. */
    public static final String REPOSITORY = "repository";

    /** Organization identifier for multi-org workspaces (e.g., "eXOReaction"). */
    public static final String ORGANIZATION = "organization";

    /** Client identifier for client-scoped files (e.g., "SpareBank1"). */
    public static final String CLIENT = "client";

    /** Sub-workspace identifier for scoped search within a workspace (e.g., "eXOReaction"). */
    public static final String SUB_WORKSPACE = "subWorkspace";

    // --- Media-specific fields ---

    /** Media type for presentation detection: "presentation", "document", "spreadsheet", etc. */
    public static final String MEDIA_TYPE = "mediaType";

    /** Image dimensions as "WxH" string (e.g., "1920x1080"). */
    public static final String DIMENSIONS = "dimensions";

    /** Duration of audio/video in seconds (stored as string). */
    public static final String DURATION = "duration";

    /** AI-generated description of an image or slide. */
    public static final String AI_DESCRIPTION = "aiDescription";

    /** Companion file path (e.g., transcript for video, metadata sidecar). */
    public static final String COMPANION_FILE = "companionFile";

    /** Source file that this companion file was generated for. */
    public static final String COMPANION_FOR = "companionFor";

    // --- Embedding fields ---

    /** Embedding vector for semantic search (KNN vector field). */
    public static final String EMBEDDING = "embedding";

    /** Embedding model used (e.g., "text-embedding-3-small"). */
    public static final String EMBEDDING_MODEL = "embeddingModel";
}
